export declare const CREATE_TABLES = "\nCREATE TABLE IF NOT EXISTS creators (\n  id TEXT PRIMARY KEY,\n  platform TEXT NOT NULL,\n  handle TEXT NOT NULL,\n  display_name TEXT,\n  channel_id TEXT,\n  category TEXT,\n  created_at BIGINT\n);\n\nCREATE TABLE IF NOT EXISTS snapshots (\n  id SERIAL PRIMARY KEY,\n  creator_id TEXT NOT NULL REFERENCES creators(id) ON DELETE CASCADE,\n  fetched_at BIGINT NOT NULL,\n  subscribers BIGINT,\n  views_total BIGINT,\n  video_count INTEGER,\n  avg_views_30d REAL,\n  engagement_rate REAL,\n  raw_json TEXT\n);\n\nCREATE TABLE IF NOT EXISTS campaigns (\n  id TEXT PRIMARY KEY,\n  creator_id TEXT NOT NULL REFERENCES creators(id) ON DELETE CASCADE,\n  brand TEXT NOT NULL,\n  campaign_name TEXT,\n  start_date BIGINT,\n  end_date BIGINT,\n  spend REAL,\n  conversions INTEGER,\n  status TEXT\n);\n\nCREATE INDEX IF NOT EXISTS idx_snapshots_creator_id ON snapshots(creator_id);\nCREATE INDEX IF NOT EXISTS idx_snapshots_fetched_at ON snapshots(fetched_at);\nCREATE INDEX IF NOT EXISTS idx_creators_platform ON creators(platform);\nCREATE INDEX IF NOT EXISTS idx_campaigns_creator_id ON campaigns(creator_id);\n";
